132	// encodedRecord is the exact byte form NormalizeReader writes for one line
133	// (json.Encoder appends a newline), used to script writer byte budgets.
134	func encodedRecord(t *testing.T, lineNo int, raw string) []byte {
135		t.Helper()
136		b, err := json.Marshal(NormalizeLine(lineNo, []byte(raw)))
137		if err != nil {
138			t.Fatal(err)
139		}
140		return append(b, '\n')
141	}
