248			t.Fatalf("the second 101-empty streak must trip at Read %d, consumed %d of %d steps", wantReads, src.i, len(steps))
249		}
250		results := decodeResults(t, out.Bytes())
251		if len(results) != 1 || results[0]["ok"] != true {
252			t.Fatalf("only the complete log before the streaks may be emitted, got %#v", results)
253		}
254		if eventOf(t, results[0])["action"] != "a" {
255			t.Fatalf("surviving record content mismatch: %#v", results[0])
256		}
257		if bytes.Contains(out.Bytes(), []byte("delivered-after-stall")) {
258			t.Fatalf("input delivered after the trip must not be read: %q", out.String())
259		}
260	}
261	
262	// Several empty stretches, each below the limit and separated by fragments
263	// of one log line, must not accumulate into a failure: counting is per
264	// consecutive streak, not cumulative. The line fragments only reunite at a
265	// clean EOF, where the newline-less final log is emitted under the existing
266	// final-line rule.
267	func TestNormalizeIOStallSubLimitStretchesDoNotAccumulate(t *testing.T) {
268		line := validLog("seg-tail")
269		if len(line) < 30 {
270			t.Fatalf("test setup: fragment split point out of range")
271		}
272		first, rest := line[:25], line[25:]
273		steps := []scriptStep{{data: []byte(validLog("a") + "\n")}}
274		steps = append(steps, emptyReadSteps(99)...)
275		steps = append(steps, scriptStep{data: []byte(first)}) // no newline yet
276		steps = append(steps, emptyReadSteps(99)...)
277		steps = append(steps, scriptStep{data: []byte(rest)}) // completes the object, still no newline
278		steps = append(steps, emptyReadSteps(99)...)
279		steps = append(steps, scriptStep{err: io.EOF})
280		src := &scriptReader{steps: steps}
281		var out bytes.Buffer
282		failures, err := NormalizeReader(src, &out)
283		if err != nil {
284			t.Fatalf("three sub-limit empty stretches (297 empty reads in total) must not fail, got %v", err)
285		}
286		if failures != 0 {
287			t.Fatalf("all logs valid, got %d failures", failures)
288		}
289		if src.i != len(steps) {
290			t.Fatalf("a healthy stream must be read to its EOF step, read %d of %d", src.i, len(steps))
291		}
292		results := decodeResults(t, out.Bytes())
293		if len(results) != 2 {
294			t.Fatalf("the fragmented final log must reassemble into one record, got %#v", results)
295		}
296		if results[0]["line"] != float64(1) || results[1]["line"] != float64(2) || results[1]["ok"] != true {
297			t.Fatalf("both logs must appear once with correct physical numbers: %#v", results)
298		}
299		if eventOf(t, results[1])["action"] != "seg-tail" {
300			t.Fatalf("fragments reunited at EOF must produce the intended final event, got %#v", results[1])
301		}
302	}
303	
304	// Sanity guard for the scripting itself: the threshold the contract names is
305	// 101 consecutive empty reads, so 101 is the smallest number that faults.
306	// This keeps the other tests' counts honest if the bound is ever adjusted.
307	func TestNormalizeIOStallThresholdIsDocumentedBoundary(t *testing.T) {
308		for _, n := range []int{101, 102} {
309			t.Run(fmt.Sprintf("%d empty reads", n), func(t *testing.T) {
310				src := &scriptReader{steps: emptyReadSteps(n)}
311				failures, err := NormalizeReader(src, &bytes.Buffer{})
312				if err == nil || !errors.Is(err, ErrLogRead) || !errors.Is(err, io.ErrNoProgress) {
313					t.Fatalf("%d consecutive empty reads must be a stall fault, got failures=%d err=%v", n, failures, err)
314				}
315				if src.i != 101 {
316					t.Fatalf("must stop exactly on the 101st empty Read regardless of script length, consumed %d", src.i)
317				}
