11	// Regression coverage for the shutdown boundary where the reader delivers
12	// log bytes and the terminal status of the stream in the SAME Read call.
13	// A clean EOF arriving together with the final bytes is normal completion
14	// (including a final line that has no trailing newline), while a non-EOF
15	// read fault arriving with identical bytes must keep every newline-ended
16	// line but must never turn the trailing fragment into an event or a line
17	// failure: whether the fragment parses as a complete, field-valid JSON
18	// object is irrelevant, because it belongs to the failed read.
19	//
20	// Every scenario is scripted through scriptReader/failWriter from
21	// normalize_io_test.go, so the boundary reproduces deterministically
22	// offline without real pipes, networks, or device failures.
23	
24	// mixedCompleteLines holds every kind of complete physical line:
25	//
26	//	line 1: a valid log
27	//	line 2: a blank line (no output, but it keeps its physical line number)
28	//	line 3: a field-invalid log (failure result with a reason)
29	//
30	// trailingFragment is a complete, field-valid JSON object WITHOUT a trailing
31	// newline: at a clean EOF it is the final complete log; under a read fault it
32	// is a fragment of the failed read.
33	func mixedCompleteLinesAndFragment() (complete, fragment string) {
34		complete = validLog("a") + "\n" +
35			"\n" +
36			`{"timestamp":"not-a-time","action":"b"}` + "\n"
37		fragment = `{"timestamp":"2026-01-02T00:00:00Z","action":"tail-fragment"}`
38		return complete, fragment
39	}
40	
41	// The same bytes delivered in one Read, terminated by a clean EOF, are
42	// normal completion: every newline-ended line is processed in physical line
43	// order, the blank line only reserves its number, and the trailing
44	// newline-less JSON log still produces a result rather than being dropped.
45	func TestNormalizeIOEOFWithBytesInSameRead(t *testing.T) {
46		complete, fragment := mixedCompleteLinesAndFragment()
47		src := &scriptReader{steps: []scriptStep{
48			// One step: all bytes and io.EOF become available together.
